     1	const { CATEGORIES } = require('./categories');
     2	
     3	const outbox = [];
     4	
     5	function sendMail({ user, template, category, message }) {
     6	  const cat = CATEGORIES[category];
     7	  if (!cat) throw new Error('unknown category ' + category);
     8	  if (cat.suppressible && user.unsubscribed) return false;
     9	  outbox.push({ to: user.email, template, category, message });
    10	  return true;
    11	}
    12	
    13	module.exports = { sendMail, outbox };

