     1	const fs = require('node:fs');
     2	const path = require('node:path');
     3	
     4	const cache = {};
     5	
     6	function table(locale) {
     7	  if (!cache[locale]) {
     8	    const file = path.join(__dirname, '..', 'locales', locale + '.json');
     9	    cache[locale] = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : null;
    10	  }
    11	  return cache[locale];
    12	}
    13	
    14	function t(locale, key, vars = {}) {
    15	  const text = (table(locale || 'en') || table('en'))[key] ?? table('en')[key];
    16	  return text.replace(/\{(\w+)\}/g, (_, name) => String(vars[name] ?? ''));
    17	}
    18	
    19	module.exports = { t };

--- src/ratelimit.js ---
     1	const hits = new Map();
     2	
     3	function allow(key, limit = 5, windowMs = 60000, now = Date.now()) {
     4	  const recent = (hits.get(key) ?? []).filter((t) => now - t < windowMs);
     5	  recent.push(now);
     6	  hits.set(key, recent);
     7	  return recent.length <= limit;
     8	}
     9	
    10	module.exports = { allow };

